def parse_cri(line):
    parts = line.split(" ", 3)
    if len(parts) != 4:
        return None
    time, stream, flag, message = parts
    return {"time": time, "stream": stream, "partial": flag == "P",
            "message": message.rstrip("\n") if flag == "F" else message}
